mapper.update:
UPDATE export_task SET stage = #{stage}, progress = #{progress}, exported_count = #{exportedCount},
    heartbeat_at = #{now}, updated_at = #{now}, version = version + 1
WHERE id = #{taskId} AND status = 'PROCESSING' AND execution_token = #{executionToken}

mapper.select:
SELECT  FROM export_task
WHERE status = 'PROCESSING' AND heartbeat_at < #{cutoff}
ORDER BY heartbeat_at LIMIT #{limit}

mapper.update:
UPDATE export_task SET status = 'PENDING', stage = 'RECOVERING', progress = 0, exported_count = 0,
    failure_code = 'WORKER_LOST', failure_message = 'Worker 心跳超时，任务将从头恢复', retryable = TRUE,
    worker_id = NULL, execution_token = NULL, heartbeat_at = NULL, updated_at = #{now}, version = version + 1
WHERE id = #{taskId} AND status = 'PROCESSING' AND execution_token = #{executionToken}
  AND heartbeat_at = #{observedHeartbeatAt}

UPDATE export_task SET status = 'FAILED', stage = 'COMPLETED', failure_code = 'WORKER_LOST',
    failure_message = 'Worker 心跳超时且自动执行次数已用尽', retryable = TRUE,
    completed_at = #{now}, updated_at = #{now}, version = version + 1
WHERE id = #{taskId} AND status = 'PROCESSING' AND execution_token = #{executionToken}
  AND heartbeat_at = #{observedHeartbeatAt}

mapper.select:
SELECT  FROM export_task
WHERE id = #{rootTaskId} OR root_task_id = #{rootTaskId}
ORDER BY manual_retry_index, id

mapper.update:
UPDATE export_task SET status = 'FAILED', stage = 'COMPLETED', failure_code = 'FILE_MISSING',
    failure_message = '导出文件不存在', retryable = FALSE, updated_at = #{now}
WHERE id = #{taskId} AND status = 'SUCCESS'

mapper.select:
SELECT  FROM export_task
WHERE status = 'SUCCESS' AND file_expire_at <= #{now}
ORDER BY file_expire_at LIMIT #{limit}

mapper.update:
UPDATE export_task SET status = 'EXPIRED', stage = 'COMPLETED', file_path = NULL,
    updated_at = #{now}, version = version + 1
WHERE id = #{taskId} AND status = 'SUCCESS' AND file_expire_at <= #{now}
